-- Deletes the signed-in shopper's account. Their saved details, bag, wishlist, payment methods and reviews are
-- removed. Orders are kept for the shop's records (accounting, refunds, returns) but lose everything that identifies
-- the shopper: name, phone, address, directions and Mobile Money number. Related support cases and return details are
-- scrubbed the same way, and queued messages are dropped. Return photos are removed by the web app first.
create function public.delete_my_account()
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user uuid := auth.uid();
  v_blocker text := public.account_deletion_blocker();
  v_orders uuid[];
begin
  if v_blocker is not null then
    raise exception '%', v_blocker using errcode = '22023';
  end if;

  select coalesce(array_agg(o.id), '{}') into v_orders from public.orders o where o.user_id = v_user;

  update public.orders o
  set user_id = null, customer_name = 'Deleted customer', phone = '', ghanapost_gps = null, rider_directions = null,
      wallet_number = case when o.wallet_number is null then null else '' end
  where o.id = any (v_orders);

  update public.support_cases s
  set name = 'Deleted customer', phone = '', email = null, message = '[Removed at the customer’s request]',
      staff_reply = null
  where s.order_id = any (v_orders);

  update public.return_requests r set details = null, photo_paths = '{}' where r.order_id = any (v_orders);
  delete from public.notifications n where n.order_id = any (v_orders);

  -- Logged without who it was: the point of deleting is that nothing identifying is kept.
  insert into public.audit_log (action, entity, details)
  values ('account.deleted', 'account', jsonb_build_object('orders_anonymised', cardinality(v_orders)));

  -- Cascades to the profile, addresses, saved numbers, bag, wishlist and reviews.
  delete from auth.users u where u.id = v_user;
  return jsonb_build_object('orders_anonymised', cardinality(v_orders));
end;
$$;

revoke all on function public.delete_my_account() from public, anon;
grant execute on function public.delete_my_account() to authenticated;

-- ===========================================================================
-- 20261023120000_launch_hardening.sql
-- ===========================================================================

-- Launch hardening: fail closed for invalid delivery configuration and preserve payment integrity.
-- The trigger protects every caller, including direct RPC attempts, rather than relying only on the checkout UI.

create or replace function public.validate_order_delivery()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_zone_id text;
  v_option_fee numeric;
  v_available boolean;
begin
  select o.fee_ghs into v_option_fee
  from public.delivery_options o
  where o.id = new.delivery_option_id;
  if not found or v_option_fee is null then
    raise exception 'This delivery option is not configured yet.' using errcode = '22023';
  end if;

  select a.zone_id into v_zone_id
  from public.delivery_areas a
  where a.name = new.area and a.is_active;
  if not found then
    raise exception 'We don''t deliver to that area yet.' using errcode = '22023';
  end if;

  if v_zone_id is not null then
    select r.is_available into v_available
    from public.delivery_rates r
    where r.zone_id = v_zone_id and r.option_id = new.delivery_option_id;
    if not found or not coalesce(v_available, false) then
      raise exception 'That delivery option is not available in this area.' using errcode = '22023';
    end if;
  end if;

  return new;
end;
$$;

revoke all on function public.validate_order_delivery() from public, anon, authenticated;

drop trigger if exists orders_validate_delivery on public.orders;
create trigger orders_validate_delivery
  before insert on public.orders
  for each row execute function public.validate_order_delivery();

-- Keep monetary payment records non-negative even if a future caller bypasses the payment RPC.
alter table public.payments
  drop constraint if exists payments_amount_ghs_check;
alter table public.payments
  add constraint payments_amount_ghs_check check (amount_ghs >= 0);

-- ===========================================================================
-- 20261023130000_catalogue_discovery_metrics.sql
-- ===========================================================================

-- Discovery metrics used by public listing pages. Counts are derived from published reviews and completed orders;
-- no customer identifiers are exposed.
create or replace function public.get_product_discovery_metrics()
returns table (slug text, average_rating numeric, review_count integer, popularity bigint)
language sql
stable
security definer
set search_path = ''
as $$
  select p.slug,
    coalesce((select round(avg(r.rating), 1) from public.product_reviews r where r.product_id = p.id and r.status = 'published'), 0)::numeric,
    coalesce((select count(*)::integer from public.product_reviews r where r.product_id = p.id and r.status = 'published'), 0),
    coalesce((select sum(oi.quantity)::bigint
      from public.order_items oi join public.orders o on o.id = oi.order_id
      where oi.product_id = p.id and o.status in ('paid', 'packing', 'packed', 'out_for_delivery', 'delivered')), 0)::bigint
  from public.products p
  where p.is_published and p.recalled_at is null;
$$;
revoke all on function public.get_product_discovery_metrics() from public;
grant execute on function public.get_product_discovery_metrics() to anon, authenticated;

