-- The "kids filter" (bath, toys, clothing, gifts) only means something for kids' products. Clear it for every other
-- department, whichever way the product is saved.
create function public.products_clear_kids_filter()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
